# FrontendServiceError
# We want to define each variant as a nested class that's also a subclass,
# which is tricky in Python.  To accomplish this we're going to create each
# class separately, then manually add the child classes to the base class's
# __dict__.  All of this happens in dummy class to avoid polluting the module
# namespace.
class FrontendServiceError(Exception):
    pass

_UniffiTempFrontendServiceError = FrontendServiceError

class FrontendServiceError:  # type: ignore
    class InvalidPath(_UniffiTempFrontendServiceError):
        def __init__(self, reason):
            super().__init__(", ".join([
                "reason={!r}".format(reason),
            ]))
            self.reason = reason

        def __repr__(self):
            return "FrontendServiceError.InvalidPath({})".format(str(self))
    _UniffiTempFrontendServiceError.InvalidPath = InvalidPath # type: ignore
    class Probe(_UniffiTempFrontendServiceError):
        def __init__(self, reason):
            super().__init__(", ".join([
                "reason={!r}".format(reason),
            ]))
            self.reason = reason

        def __repr__(self):
            return "FrontendServiceError.Probe({})".format(str(self))
    _UniffiTempFrontendServiceError.Probe = Probe # type: ignore
    class Plot(_UniffiTempFrontendServiceError):
        def __init__(self, reason):
            super().__init__(", ".join([
                "reason={!r}".format(reason),
            ]))
            self.reason = reason

        def __repr__(self):
            return "FrontendServiceError.Plot({})".format(str(self))
    _UniffiTempFrontendServiceError.Plot = Plot # type: ignore
    class Parameters(_UniffiTempFrontendServiceError):
        def __init__(self, reason):
            super().__init__(", ".join([
                "reason={!r}".format(reason),
            ]))
            self.reason = reason

        def __repr__(self):
            return "FrontendServiceError.Parameters({})".format(str(self))
    _UniffiTempFrontendServiceError.Parameters = Parameters # type: ignore
    class TaskCompletion(_UniffiTempFrontendServiceError):
        def __init__(self, reason):
            super().__init__(", ".join([
                "reason={!r}".format(reason),
            ]))
            self.reason = reason

        def __repr__(self):
            return "FrontendServiceError.TaskCompletion({})".format(str(self))
    _UniffiTempFrontendServiceError.TaskCompletion = TaskCompletion # type: ignore

FrontendServiceError = _UniffiTempFrontendServiceError # type: ignore
del _UniffiTempFrontendServiceError


class _UniffiConverterTypeFrontendServiceError(_UniffiConverterRustBuffer):
    @staticmethod
    def read(buf):
        variant = buf.read_i32()
        if variant == 1:
            return FrontendServiceError.InvalidPath(
                _UniffiConverterString.read(buf),
            )
        if variant == 2:
            return FrontendServiceError.Probe(
                _UniffiConverterString.read(buf),
            )
        if variant == 3:
            return FrontendServiceError.Plot(
                _UniffiConverterString.read(buf),
            )
        if variant == 4:
            return FrontendServiceError.Parameters(
                _UniffiConverterString.read(buf),
            )
        if variant == 5:
            return FrontendServiceError.TaskCompletion(
                _UniffiConverterString.read(buf),
            )
        raise InternalError("Raw enum value doesn't match any cases")

    @staticmethod
    def check_lower(value):
        if isinstance(value, FrontendServiceError.InvalidPath):
            _UniffiConverterString.check_lower(value.reason)
            return
        if isinstance(value, FrontendServiceError.Probe):
            _UniffiConverterString.check_lower(value.reason)
            return
        if isinstance(value, FrontendServiceError.Plot):
            _UniffiConverterString.check_lower(value.reason)
            return
        if isinstance(value, FrontendServiceError.Parameters):
            _UniffiConverterString.check_lower(value.reason)
            return
        if isinstance(value, FrontendServiceError.TaskCompletion):
            _UniffiConverterString.check_lower(value.reason)
            return

    @staticmethod
    def write(value, buf):
        if isinstance(value, FrontendServiceError.InvalidPath):
            buf.write_i32(1)
            _UniffiConverterString.write(value.reason, buf)
        if isinstance(value, FrontendServiceError.Probe):
            buf.write_i32(2)
            _UniffiConverterString.write(value.reason, buf)
        if isinstance(value, FrontendServiceError.Plot):
            buf.write_i32(3)
            _UniffiConverterString.write(value.reason, buf)
        if isinstance(value, FrontendServiceError.Parameters):
            buf.write_i32(4)
            _UniffiConverterString.write(value.reason, buf)
        if isinstance(value, FrontendServiceError.TaskCompletion):
            buf.write_i32(5)
            _UniffiConverterString.write(value.reason, buf)





